/// <summary>
/// This is a controller class
/// CB355_DutyRoll
/// </summary>
final class METDutyRollMonthlyController extends SysOperationServiceController
{
}

Method.Source:
/// <summary>
/// This method creates new instances
/// </summary>
protected void new()
{
    super(classStr(METDutyRollMonthlyService), methodStr(METDutyRollMonthlyService, process), SysOperationExecutionMode::Synchronous);
}

    /// <summary>
    /// Initializes data contract.
    /// </summary>
    private void initContract()
    {
        METDutyRollMonthlyContract contract;

        contract = this.getDataContractObject() as METDutyRollMonthlyContract;

        if (contract)
        {
            METExciseDutyParameteres exciseDutyParameteres = METExciseDutyParameteres::Find();

            contract.parmThreadCount(exciseDutyParameteres.DutyRollMonthlyThreadCount);
        }
    }

/// <summary>
/// Main method
/// </summary>
/// <param name = "_args">Args</param>
public static void main(Args _args)
{
    METDutyRollMonthlyController controller = new METDutyRollMonthlyController();
    controller.parmArgs(_args);
    controller.initContract();
    controller.startOperation();
}

/// <summary>
/// The caption method of the batch job dialog.
/// </summary>
/// <returns>String value to be used on dialog</returns>
public ClassDescription caption()
{
    return "@MET:MonthlyDutyRoll";
}

/// <summary>
/// to avoid multiple runs at the same time
/// </summary>
/// <returns>true always</returns>
public boolean mustGoBatch()
{
    return true;
}

/// <summary>
/// Can run in new session
/// </summary>
/// <returns>
/// true if can run in new session; otherwise, false.
/// </returns>
protected boolean canRunInNewSession()
{
    return true;
}
